const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const TRACKS=[['derive','Derive it','Work from the assumptions to the result.'],['graph','Build the graph','Choose axes, draw each relationship, then locate the outcome.'],['increase','↑ Increase','Increase the stated variable and follow each channel with the named assumptions fixed.'],['decrease','↓ Decrease','Decrease the stated variable and work through each adjustment in order.'],['edge','Edge cases','Find the failed assumption and redo the affected step.']];
const colors={base:'#6a8753',new:'#8864c2',reference:'#4d83be',other:'#c17d48'};
function curveColors(figure){const palette=['#6a8753','#4d83be','#8864c2','#c17d48','#238c86','#b45664','#8d762c','#5664a5','#607f8f','#ab6aa4','#477650','#9f603e','#464d80','#789a28','#a24978','#277eaa','#797167','#9a428f','#306b64','#815635'];const used=new Set(),result={};for(const c of figure.curves){let color=colors[c.role]||colors.base;if(used.has(color))color=palette.find(v=>!used.has(v))||palette[used.size%palette.length];used.add(color);result[c.id]=color}return result}
let contentPromise;
export const loadWalkthroughs=()=>contentPromise??=(fetch('walkthroughs.json?v=4').then(r=>{if(!r.ok)throw Error('Guided walkthroughs could not be loaded');return r.json()}));
export function cleanWalkProgress(value,concepts){const clean={};if(!value||typeof value!=='object')return clean;for(const [id,p] of Object.entries(value)){if(!concepts.has(id)||!p||typeof p!=='object')continue;const seen={},predictions={};for(const [t] of TRACKS){seen[t]=[...new Set((Array.isArray(p.seen?.[t])?p.seen[t]:[]).filter(n=>Number.isInteger(n)&&n>=0&&n<100))]}for(const[k,v]of Object.entries(p.predictions||{})){if(/^(derive|graph|increase|decrease|edge)-\d{1,2}$/.test(k)&&typeof v==='string')predictions[k]=v.slice(0,2000)}clean[id]={track:TRACKS.some(([t])=>t===p.track)?p.track:'derive',index:Math.max(0,Math.min(99,Math.floor(Number(p.index)||0))),seen,predictions}}return clean}
const number=n=>Math.abs(n)>=1000?Number(n.toPrecision(4)).toLocaleString():Number(n.toFixed(3)).toString();
function visibleFigure(figure,step){const shown=new Set(step.show||((figure.kind==='flow'?figure.nodes:figure.curves)||[]).map(c=>c.id));return {...figure,curves:(figure.curves||[]).filter(c=>shown.has(c.id)),nodes:(figure.nodes||[]).filter(n=>shown.has(n.id)),points:(figure.points||[]).filter(p=>(step.points||[]).includes(p.id))}}
export function plotFigure(figure,step={},highlight=''){
 const colorFor=curveColors(figure),fig=visibleFigure(figure,step),W=680,H=400,L=70,R=650,T=45,B=338,[xmin,xmax]=fig.xRange,[ymin,ymax]=fig.yRange,x=n=>L+(n-xmin)/(xmax-xmin)*(R-L),y=n=>B-(n-ymin)/(ymax-ymin)*(B-T);
 let s=`<svg class="walk-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${E(fig.title)}. Horizontal axis ${E(fig.xLabel)}. Vertical axis ${E(fig.yLabel)}."><title>${E(fig.title)}</title><desc>${E(fig.note)}</desc><defs><clipPath id="walk-clip"><rect x="${L}" y="${T}" width="${R-L}" height="${B-T}"/></clipPath></defs>`;
 for(let i=0;i<=4;i++){let a=ymin+(ymax-ymin)*i/4,b=xmin+(xmax-xmin)*i/4;s+=`<path d="M${L} ${y(a)}H${R}" stroke="#e5e9df"/><text x="${L-10}" y="${y(a)+4}" text-anchor="end">${number(a)}</text><text x="${x(b)}" y="${B+21}" text-anchor="middle">${number(b)}</text>`}
 s+=`<path d="M${L} ${T}V${B}H${R}" fill="none" stroke="#94a28e"/><text x="${L}" y="20" class="axis-label">${E(fig.yLabel)}</text><text x="${R}" y="${H-18}" text-anchor="end" class="axis-label">${E(fig.xLabel)}</text>`;
 for(const c of fig.curves){const path=c.points.filter(p=>p.every(Number.isFinite)).map((p,i)=>`${i?'L':'M'}${x(p[0]).toFixed(2)},${y(p[1]).toFixed(2)}`).join(' ');s+=`<path data-curve="${E(c.id)}" d="${path}" stroke="${colorFor[c.id]}" stroke-width="${highlight===c.id?4:2.5}" ${c.dashed?'stroke-dasharray="7 5"':''} opacity="${highlight&&highlight!==c.id?.25:1}" fill="none" clip-path="url(#walk-clip)"><title>${E(c.label)}</title></path>`}
 for(const p of fig.points){if(p.x<xmin||p.x>xmax||p.y<ymin||p.y>ymax)continue;const right=x(p.x)>R-95;s+=`<path d="M${L} ${y(p.y)}H${x(p.x)}V${B}" stroke="#aebc9f" stroke-dasharray="4 4" fill="none"/><circle cx="${x(p.x)}" cy="${y(p.y)}" r="5" fill="#254e3b" stroke="white" stroke-width="2"><title>${E(p.label)} (${number(p.x)}, ${number(p.y)})</title></circle><text x="${x(p.x)+(right?-9:9)}" y="${y(p.y)-10}" text-anchor="${right?'end':'start'}" class="point-label">${E(p.label)}</text>`}
 s+='<g id="walk-crosshair" hidden><path fill="none" stroke="#9aab8f" stroke-dasharray="3 3"/><circle r="3" fill="#173c32"/></g></svg>';
 return `<div class="walk-figure-head"><strong>${E(fig.title)}</strong><div class="walk-figure-tools"><span class="small">Numerical teaching illustration</span><button class="inline-link" data-expand-plot>Expand graph ↗</button></div></div><div class="walk-legend">${fig.curves.map(c=>`<button data-highlight="${E(c.id)}" aria-pressed="${highlight===c.id}" title="Highlight ${E(c.label)}"><i style="background:${colorFor[c.id]};${c.dashed?'opacity:.55':''}"></i>${E(c.label)}</button>`).join('')}</div>${s}<p class="walk-coordinates" aria-live="polite">Move over the graph to read axis coordinates. Select a legend item to trace one curve.</p><p class="walk-figure-note">${E(fig.note)}</p>${fig.points.length?`<details class="walk-values"><summary>Read the plotted points</summary><table><thead><tr><th>Point</th><th>${E(fig.xLabel)}</th><th>${E(fig.yLabel)}</th></tr></thead><tbody>${fig.points.map(p=>`<tr><td>${E(p.label)}</td><td>${number(p.x)}</td><td>${number(p.y)}</td></tr>`).join('')}</tbody></table></details>`:''}`;
}
export function flowFigure(figure,step={}){const fig=visibleFigure(figure,step),ids=new Set(fig.nodes.map(n=>n.id));return `<div class="walk-figure-head"><strong>${E(fig.title)}</strong><span class="small">Reasoning map</span></div><ol class="walk-flow">${fig.nodes.map(n=>`<li><strong>${E(n.label)}</strong><p>${E(n.detail)}</p></li>`).join('')}</ol>${(fig.edges||[]).filter(([a,b])=>ids.has(a)&&ids.has(b)).length?`<div class="walk-flow-links">${fig.edges.filter(([a,b])=>ids.has(a)&&ids.has(b)).map(([a,b])=>`${E(fig.nodes.find(n=>n.id===a)?.label)} <span aria-label="leads to">→</span> ${E(fig.nodes.find(n=>n.id===b)?.label)}`).join('<br>')}</div>`:''}<p class="walk-figure-note">${E(fig.note)}</p>`}
export async function mountWalkthrough(container,conceptId,{store,save}){
 container.innerHTML='<div class="walk-loading">Opening the guided walkthrough…</div>';
 try{const data=await loadWalkthroughs();if(!container.isConnected)return;const walk=data.walks[conceptId];if(!walk){container.innerHTML='';return}store.walks=store.walks||{};const state=store.walks[conceptId]||(store.walks[conceptId]={track:'derive',index:0,seen:{},predictions:{}});state.seen=state.seen||{};state.predictions=state.predictions||{};if(!walk.tracks[state.track])state.track='derive';let highlight='',all=false;
 const draw=()=>{const steps=walk.tracks[state.track];state.index=Math.max(0,Math.min(steps.length-1,Math.floor(Number(state.index)||0)));const i=state.index,step=steps[i];const seen=state.seen[state.track]||(state.seen[state.track]=[]);if(!seen.includes(i))seen.push(i);save();const visited=TRACKS.reduce((n,[t])=>n+(state.seen[t]||[]).filter(k=>k<walk.tracks[t].length).length,0),total=TRACKS.reduce((n,[t])=>n+walk.tracks[t].length,0),fig=step.figure?data.figures[step.figure]:null,token=state.track+'-'+i;
 container.innerHTML=`<div class="walk-heading"><div><p class="eyebrow">GUIDED WALKTHROUGH</p><h3>Make each step make sense.</h3><p>${E(walk.goal)}</p></div><span class="walk-visited">${visited} / ${total} steps visited</span></div><details class="walk-setup"><summary>Before you start · symbols and assumptions</summary><div class="walk-setup-grid"><dl>${walk.symbols.map(s=>`<div><dt>${E(s.symbol)}</dt><dd>${E(s.meaning)}</dd></div>`).join('')}</dl><ul>${walk.assumptions.map(a=>`<li>${E(a)}</li>`).join('')}</ul></div></details><div class="walk-tabs" role="tablist" aria-label="Walkthrough sequence">${TRACKS.map(([t,label])=>`<button id="walk-tab-${t}" role="tab" aria-selected="${state.track===t}" aria-controls="walk-current" data-track="${t}" tabindex="${state.track===t?0:-1}" class="${state.track===t?'active':''}">${label}<span>${(state.seen[t]||[]).filter(k=>k<walk.tracks[t].length).length}/${walk.tracks[t].length}</span></button>`).join('')}</div><p class="walk-track-intro">${E(state.track==='graph'&&fig?.kind==='flow'?'Build the reasoning map one relationship at a time.':TRACKS.find(([t])=>t===state.track)[2])}</p><div class="walk-step-picker"><label for="walk-step-select">Go to a step</label><select id="walk-step-select">${steps.map((s,j)=>`<option value="${j}" ${i===j?'selected':''}>${j+1}. ${E(s.title)}</option>`).join('')}</select><button class="quiet" id="walk-all" aria-expanded="${all}">${all?'Return to one step':'Read the whole sequence'}</button></div>${all?`<ol class="walk-complete">${steps.map((s,j)=>`<li><h4>${j+1}. ${E(s.title)}</h4>${s.math?`<div class="walk-math">${E(s.math)}</div>`:''}<p>${E(s.why)}</p>${s.question?`<details><summary>${E(s.question)}</summary><p>${E(s.answer)}</p></details>`:''}<button class="inline-link" data-jump="${j}">Explore this step${s.figure?' and its diagram':''} →</button></li>`).join('')}</ol>`:''}<div id="walk-current" role="tabpanel" aria-labelledby="walk-tab-${state.track}" ${all?'hidden':''}><div class="walk-workbench ${fig?'has-figure':''}"><div class="walk-reason"><p class="eyebrow">STEP ${i+1} OF ${steps.length}</p><h4 tabindex="-1" id="walk-step-title">${E(step.title)}</h4>${step.math?`<div class="walk-math">${E(step.math)}</div>`:''}<p class="walk-why">${E(step.why)}</p>${step.question?`<div class="walk-predict"><label for="walk-prediction">Pause and explain</label><p>${E(step.question)}</p><textarea id="walk-prediction" rows="3" maxlength="2000" placeholder="Put the mechanism in your own words…">${E(state.predictions[token]||'')}</textarea><details id="walk-answer"><summary>Compare the reasoning</summary><p>${E(step.answer)}</p></details></div>`:''}</div>${fig?`<div class="walk-diagram">${fig.kind==='plot'?plotFigure(fig,step,highlight):flowFigure(fig,step)}</div>`:''}</div><div class="walk-navigation"><button class="secondary" id="walk-prev" ${i===0?'disabled':''}>← Previous step</button><span>${i+1} / ${steps.length}</span><button class="primary" id="walk-next">${i<steps.length-1?'Next step →':state.track!=='edge'?'Next sequence →':'Try the experiment ↓'}</button></div></div><p class="walk-sources">${walk.sources.map(s=>`${E(s.file)} · PDF pp ${E(s.pages)}`).join('<br>')}</p>`;
 const go=(track,index,focus=true)=>{state.track=track;state.index=index;highlight='';all=false;draw();if(focus)container.querySelector('#walk-step-title')?.focus({preventScroll:true})};
 container.querySelectorAll('[data-track]').forEach(b=>{b.onclick=()=>go(b.dataset.track,0);b.onkeydown=e=>{const pos=TRACKS.findIndex(([t])=>t===b.dataset.track);let next;if(e.key==='ArrowRight')next=(pos+1)%5;if(e.key==='ArrowLeft')next=(pos+4)%5;if(e.key==='Home')next=0;if(e.key==='End')next=4;if(next!==undefined){e.preventDefault();go(TRACKS[next][0],0,false);container.querySelector(`[data-track="${TRACKS[next][0]}"]`).focus()}}});
 container.querySelector('#walk-step-select').onchange=e=>go(state.track,Number(e.target.value));container.querySelector('#walk-all').onclick=()=>{all=!all;draw()};container.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>go(state.track,Number(b.dataset.jump)));
 container.querySelector('#walk-prev').onclick=()=>go(state.track,i-1);container.querySelector('#walk-next').onclick=()=>{if(i<steps.length-1)go(state.track,i+1);else if(state.track!=='edge')go(TRACKS[TRACKS.findIndex(([t])=>t===state.track)+1][0],0);else document.querySelector('#chapter-lab')?.scrollIntoView({behavior:'smooth',block:'start'})};
 container.querySelector('#walk-prediction')?.addEventListener('input',e=>{state.predictions[token]=e.target.value;save()});
 container.querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>{highlight=highlight===b.dataset.highlight?'':b.dataset.highlight;const active=b.dataset.highlight;draw();container.querySelector(`[data-highlight="${active}"]`)?.focus({preventScroll:true})});
 container.querySelector('[data-expand-plot]')?.addEventListener('click',()=>{const dialog=document.createElement('dialog');dialog.className='walk-zoom';dialog.innerHTML=`<div class="walk-zoom-heading"><h3>${E(fig.title)}</h3><button class="secondary" data-close-plot>Close ×</button></div><p class="small">On a narrow screen, scroll across the graph to inspect the axes and points.</p><div class="walk-zoom-scroll"><div class="walk-zoom-inner">${plotFigure(fig,step,highlight).replaceAll('walk-clip','walk-zoom-clip').replaceAll('walk-crosshair','walk-zoom-crosshair')}</div></div>`;dialog.querySelector('[data-expand-plot]')?.remove();dialog.querySelector('.walk-coordinates')?.remove();dialog.querySelectorAll('[data-highlight]').forEach(b=>{b.disabled=true;b.removeAttribute('title')});document.body.appendChild(dialog);dialog.querySelector('[data-close-plot]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal()});
 if(fig?.kind==='plot'){const svg=container.querySelector('.walk-svg'),readout=container.querySelector('.walk-coordinates');svg.addEventListener('pointermove',e=>{const m=svg.getScreenCTM();if(!m)return;const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse());if(pt.x<70||pt.x>650||pt.y<45||pt.y>338)return;const px=fig.xRange[0]+(pt.x-70)/580*(fig.xRange[1]-fig.xRange[0]),py=fig.yRange[0]+(338-pt.y)/293*(fig.yRange[1]-fig.yRange[0]);readout.textContent=`${fig.xLabel} = ${number(px)} · ${fig.yLabel} = ${number(py)}. Cursor coordinates, not an equilibrium claim.`;const g=svg.querySelector('#walk-crosshair');g.removeAttribute('hidden');g.querySelector('path').setAttribute('d',`M70 ${pt.y}H${pt.x}V338`);g.querySelector('circle').setAttribute('cx',pt.x);g.querySelector('circle').setAttribute('cy',pt.y)});svg.addEventListener('pointerleave',()=>svg.querySelector('#walk-crosshair')?.setAttribute('hidden',''))}
 };draw();
 }catch(err){if(container.isConnected){container.innerHTML=`<div class="note">${E(err.message)}. Your concept reference and interactive experiment remain available below.</div>`;container.parentElement.querySelector('.concept-reference')?.setAttribute('open','')}}
}
